import { test } from 'node:test';
import assert from 'node:assert';
import {
  createInvoice,
  lineTotal,
  lineDiscount,
  invoiceTotals,
  addLine,
  removeLine,
  issueInvoice,
} from '../src/invoices.js';

test('createInvoice without discounts', () => {
  const result = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2 }],
  });

  assert.ok(result.ok);
  assert.strictEqual(result.value.status, 'draft');
  assert.strictEqual(result.value.lines[0].discountPercent, 0);
});

test('createInvoice with zero discount', () => {
  const result = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: 0 }],
  });

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].discountPercent, 0);
});

test('createInvoice with decimal discount', () => {
  const result = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: 12.5 }],
  });

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].discountPercent, 12.5);
});

test('createInvoice with 100 percent discount', () => {
  const result = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: 100 }],
  });

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].discountPercent, 100);
});

test('createInvoice rejects negative discount', () => {
  const result = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: -5 }],
  });

  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'DISCOUNT_INVALID');
});

test('createInvoice rejects discount over 100', () => {
  const result = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: 101 }],
  });

  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'DISCOUNT_INVALID');
});

test('createInvoice rejects non-numeric discount', () => {
  const result = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: 'twenty' }],
  });

  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'DISCOUNT_INVALID');
});

test('lineTotal calculates correctly', () => {
  const line = { qty: 5, unitPrice: 1000 };
  assert.strictEqual(lineTotal(line), 5000);
});

test('lineDiscount without discount field defaults to 0', () => {
  const line = { qty: 5, unitPrice: 1000 };
  assert.strictEqual(lineDiscount(line), 0);
});

test('lineDiscount with 0 percent discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 0 };
  assert.strictEqual(lineDiscount(line), 0);
});

test('lineDiscount with 10 percent discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 10 };
  assert.strictEqual(lineDiscount(line), 500);
});

test('lineDiscount with 50 percent discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 50 };
  assert.strictEqual(lineDiscount(line), 2500);
});

test('lineDiscount with 100 percent discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 100 };
  assert.strictEqual(lineDiscount(line), 5000);
});

test('lineDiscount with decimal discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 12.5 };
  assert.strictEqual(lineDiscount(line), 625);
});

test('invoiceTotals without discounts', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000 },
      { qty: 3, unitPrice: 2000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, {
    subtotal: 8000,
    discount: 0,
    total: 8000,
  });
});

test('invoiceTotals with single line discount', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, {
    subtotal: 2000,
    discount: 200,
    total: 1800,
  });
});

test('invoiceTotals with multiple line discounts', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, discountPercent: 10 },
      { qty: 3, unitPrice: 2000, discountPercent: 20 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, {
    subtotal: 8000,
    discount: 200 + 1200,
    total: 6600,
  });
});

test('invoiceTotals with 100 percent discount on one line', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000 },
      { qty: 3, unitPrice: 2000, discountPercent: 100 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, {
    subtotal: 8000,
    discount: 6000,
    total: 2000,
  });
});

test('invoiceTotals with all discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 100 },
      { qty: 5, unitPrice: 2000, discountPercent: 100 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, {
    subtotal: 20000,
    discount: 20000,
    total: 0,
  });
});

test('addLine without discount', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'GADGET', qty: 1 });

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[1].discountPercent, 0);
});

test('addLine with discount', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'GADGET', qty: 1, discountPercent: 25 });

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[1].discountPercent, 25);
});

test('addLine rejects invalid discount', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'GADGET', qty: 1, discountPercent: 150 });

  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'DISCOUNT_INVALID');
});

test('removeLine preserves discounts on remaining lines', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WIDGET', qty: 2, discountPercent: 10 },
      { sku: 'GADGET', qty: 1, discountPercent: 20 },
    ],
  }).value;

  const result = removeLine(invoice, 'WIDGET');

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].sku, 'GADGET');
  assert.strictEqual(result.value.lines[0].discountPercent, 20);
});

test('issueInvoice with discounts', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: 10 }],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].discountPercent, 10);
  assert.strictEqual(result.value.status, 'issued');
});

test('amounts are clamped to zero (no negatives)', () => {
  const line = { qty: 0, unitPrice: 1000 };
  assert.strictEqual(lineTotal(line), 0);

  const invoice = {
    lines: [
      { qty: 0, unitPrice: 1000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.ok(totals.subtotal >= 0);
  assert.ok(totals.discount >= 0);
  assert.ok(totals.total >= 0);
});

