    discount: 6000,
    total: 2000,
  });
});

test('invoiceTotals with all discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 100 },
      { qty: 5, unitPrice: 2000, discountPercent: 100 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, {
    subtotal: 20000,
    discount: 20000,
