  });
});

test('addLine without discount', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'GADGET', qty: 1 });

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[1].discountPercent, 0);
});

test('addLine with discount', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'GADGET', qty: 1, discountPercent: 25 });

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[1].discountPercent, 25);
});

test('addLine rejects invalid discount', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'GADGET', qty: 1, discountPercent: 150 });

  assert.ok(!result.ok);
  assert.strictEqual(result.error, 'DISCOUNT_INVALID');
});

test('removeLine preserves discounts on remaining lines', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WIDGET', qty: 2, discountPercent: 10 },
      { sku: 'GADGET', qty: 1, discountPercent: 20 },
    ],
  }).value;

  const result = removeLine(invoice, 'WIDGET');

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].sku, 'GADGET');
  assert.strictEqual(result.value.lines[0].discountPercent, 20);
});

test('issueInvoice with discounts', () => {
  const invoice = createInvoice({
    customerId: 'cust_1',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WIDGET', qty: 2, discountPercent: 10 }],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.ok(result.ok);
  assert.strictEqual(result.value.lines[0].discountPercent, 10);
  assert.strictEqual(result.value.status, 'issued');
});

test('amounts are clamped to zero (no negatives)', () => {
  const line = { qty: 0, unitPrice: 1000 };
  assert.strictEqual(lineTotal(line), 0);

  const invoice = {
    lines: [
      { qty: 0, unitPrice: 1000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.ok(totals.subtotal >= 0);
  assert.ok(totals.discount >= 0);
  assert.ok(totals.total >= 0);
});

