test('addLine and removeLine preserve other invoice properties', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  const invoice = invoiceResult.value;
  let modified = addLine(invoice, { sku: 'COPY-HOUR', qty: 1 }).value;

  assert.strictEqual(modified.customerId, 'C-001');
  assert.strictEqual(modified.issueDate, '2025-12-15');
  assert.strictEqual(modified.status, 'draft');

  modified = removeLine(modified, 'DEV-HOUR').value;

  assert.strictEqual(modified.customerId, 'C-001');
  assert.strictEqual(modified.issueDate, '2025-12-15');
  assert.strictEqual(modified.status, 'draft');
});

